#!/usr/bin/env python3
"""Static checks that keep GameTests product UI on the shared system (ui/VISUAL_GUIDE.md).

Only product UI is checked. Game art may break any rule; mark such a line with `# gt:art`.

Godot games (every .gd outside addons/, tests/, tools/):
  setup        the game calls GTUI.setup(...) (palette + scale)
  helpers      a product-UI helper (a function named like *button*, *toast*, *modal*, *archive*,
               *help*, *header*, *calendar*, *dim*) that draws must go through GTUI, directly or via
               a local helper that does
  tokens       GTUI text/box calls use the tokens: font sizes are GTUI.FS_*, radii are GTUI.R_*
  no-tab       Tab is reserved for keyboard focus: no game action may bind KEY_TAB
  no-effects   no shadow_size / Gradient in product-UI helpers
  font-sizes   the number of distinct literal font sizes passed to draw_string() may not grow
               beyond the recorded baseline (.github/ui-lint-baseline.json); new UI uses GTUI.FS_*

Home page (generated by make-index.py):
  radii only 0 / 6px / 8px / var(--r-*); no box-shadow, no gradients; no ellipsis truncation;
  padding/margin/gap only from the spacing scale (0 1 2 4 8 12 16 24 32 48 px or var(--s*)).

Usage: ui-lint.py [--update-baseline]
"""
import json
import pathlib
import re
import subprocess
import sys
import tempfile

ROOT = pathlib.Path(__file__).resolve().parents[2]
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
from gamelist import find_games  # noqa: E402

BASELINE = ROOT / ".github" / "ui-lint-baseline.json"
HELPER = re.compile(r"^(?:static )?func (_?(?:draw_)?\w*(?:button|btn|toast|modal|archive|help|header|calendar|dim)\w*)\(")
FUNC = re.compile(r"^(?:static )?func (\w+)\(")
DRAWS = re.compile(r"\bdraw_(string|style_box|rect|circle|multiline_string)\(")
ART = "# gt:art"


def gd_files(folder):
    for f in sorted(folder.rglob("*.gd")):
        rel = f.relative_to(folder).parts
        if rel[0] in ("addons", "tests", "tools"):
            continue
        yield f


def functions(lines):
    """[(name, start, end)] for top-level functions."""
    out = []
    i = 0
    while i < len(lines):
        m = FUNC.match(lines[i])
        if not m:
            i += 1
            continue
        j = i + 1
        while j < len(lines) and (lines[j] == "" or lines[j][0] in "\t #"):
            if lines[j].startswith("#") and not lines[j].startswith("##"):
                break
            j += 1
        out.append((m.group(1), i, j))
        i = j
    return out


def split_args(s, start):
    """Arguments of the call whose '(' is at s[start]; returns (args, end_index)."""
    depth, cur, args, i, q = 0, "", [], start, None
    while i < len(s):
        ch = s[i]
        if q:
            cur += ch
            if ch == q and s[i - 1] != "\\":
                q = None
        elif ch in "\"'":
            q = ch
            cur += ch
        elif ch in "([{":
            depth += 1
            if depth > 1:
                cur += ch
        elif ch in ")]}":
            depth -= 1
            if depth == 0:
                args.append(cur.strip())
                return args, i
            cur += ch
        elif ch == "," and depth == 1:
            args.append(cur.strip())
            cur = ""
        else:
            cur += ch
        i += 1
    return args, i


# GTUI call -> index of the argument that must be a token, and which token family
TOKEN_ARGS = {
    "GTUI.text": (3, "FS_"), "GTUI.text_in": (3, "FS_"), "GTUI.paragraph": (5, "FS_"),
    "GTUI.text_width": (1, "FS_"), "GTUI.line_height": (0, "FS_"), "GTUI.fs": (0, "FS_"),
    "GTUI.box": (3, "R_"),
}


def lint_game(folder, slug, problems, metrics):
    texts = {f: f.read_text() for f in gd_files(folder)}
    all_src = "\n".join(texts.values())
    if "GTUI.setup(" not in all_src:
        problems.append(f"{slug}: never calls GTUI.setup() (supply the game's palette)")
    sizes = set()
    # local helpers that delegate to GTUI
    backed = set()
    for src in texts.values():
        lines = src.split("\n")
        for name, a, b in functions(lines):
            if "GTUI." in "\n".join(lines[a:b]):
                backed.add(name)
    for f, src in texts.items():
        rel = f.relative_to(ROOT)
        lines = src.split("\n")
        for k, line in enumerate(lines):
            if ART in line:
                continue
            code = line.split("#", 1)[0]
            if "KEY_TAB" in code:
                problems.append(f"{rel}:{k + 1}: binds Tab, which is reserved for keyboard focus")
            for call, (idx, fam) in TOKEN_ARGS.items():
                for m in re.finditer(re.escape(call) + r"\(", code):
                    args, _ = split_args(code, m.end() - 1)
                    if idx < len(args):
                        arg = args[idx]
                        if re.fullmatch(r"-?\d+(\.\d+)?", arg):
                            problems.append(f"{rel}:{k + 1}: {call}() takes a GTUI.{fam}* token, not {arg}")
            for m in re.finditer(r"\bdraw_string\(", code):
                args, _ = split_args(code, m.end() - 1)
                if len(args) >= 6 and re.fullmatch(r"\d+", args[5]):
                    sizes.add(int(args[5]))
        for name, a, b in functions(lines):
            if not HELPER.match(lines[a]):
                continue
            body = "\n".join(l for l in lines[a:b] if ART not in l)
            if re.search(r"shadow_size|Gradient", body):
                problems.append(f"{rel}:{a + 1}: {name}() is product UI: no shadows or gradients (borders and contrast instead)")
            if DRAWS.search(body) or re.search(r"\b_(rr|box|round_rect|rrect)\(", body):
                calls = set(re.findall(r"\b(\w+)\(", body))
                if "GTUI." not in body and not (calls & backed):
                    problems.append(f"{rel}:{a + 1}: {name}() draws product UI without GTUI")
    metrics[slug] = {"literal_font_sizes": len(sizes)}


SPACING = {"0", "1px", "2px", "4px", "8px", "12px", "16px", "24px", "32px", "48px"}


def lint_homepage(problems):
    with tempfile.TemporaryDirectory() as tmp:
        site = pathlib.Path(tmp)
        for folder, slug, _ in find_games(ROOT / "games"):
            (site / slug).mkdir()
            (site / slug / "index.html").write_text("")
        r = subprocess.run([sys.executable, str(ROOT / ".github/scripts/make-index.py"), str(ROOT / "games"), str(site)],
                           capture_output=True, text=True)
        if r.returncode:
            problems.append("homepage: make-index.py failed: " + r.stdout + r.stderr)
            return
        page = (site / "index.html").read_text()
    css = page[page.index("<style>"):page.index("</style>")]
    for m in re.finditer(r"border-radius:([^;}]+)", css):
        for v in m.group(1).split():
            if v not in ("0", "6px", "8px") and not v.startswith("var(--r-"):
                problems.append(f"homepage: border-radius {v} is not 6px / 8px / var(--r-*)")
    if "box-shadow" in css:
        problems.append("homepage: no box-shadow in product chrome")
    if "gradient(" in page:
        problems.append("homepage: no gradients in product chrome")
    if re.search(r"line-clamp|text-overflow\s*:\s*ellipsis", css):
        problems.append("homepage: text is never truncated with an ellipsis (no line-clamp / text-overflow)")
    for m in re.finditer(r"(?<![-\w])(padding|margin|gap|column-gap|row-gap)(?:-\w+)?:([^;}]+)", css):
        for v in m.group(2).split():
            v = v.strip()
            if v in SPACING or v.startswith("var(--s") or v.startswith("calc(") or v in ("auto", "!important"):
                continue
            if re.fullmatch(r"-?\d*\.?\d+(rem|em|%)", v):
                problems.append(f"homepage: {m.group(1)} {v}: use px from the spacing scale")
            elif re.fullmatch(r"-?\d+px", v):
                problems.append(f"homepage: {m.group(1)} {v} is not on the spacing scale")


def main():
    problems = []
    metrics = {}
    for folder, slug, _ in find_games(ROOT / "games"):
        lint_game(folder, slug, problems, metrics)
    lint_homepage(problems)
    if "--update-baseline" in sys.argv:
        BASELINE.write_text(json.dumps(metrics, indent=2, sort_keys=True) + "\n")
        print(f"wrote {BASELINE.relative_to(ROOT)}")
    base = json.loads(BASELINE.read_text()) if BASELINE.exists() else {}
    for slug, m in metrics.items():
        allowed = base.get(slug, {}).get("literal_font_sizes", 0)
        if m["literal_font_sizes"] > allowed:
            problems.append(f"{slug}: {m['literal_font_sizes']} distinct literal font sizes in draw_string() (baseline {allowed}); "
                            "use GTUI.FS_* for product text, or mark deliberate game-art text with # gt:art")
    for p in problems:
        print(f"::error::{p}")
    if problems:
        sys.exit(1)
    print(f"ui-lint: {len(metrics)} games and the home page follow the shared UI rules")


if __name__ == "__main__":
    main()
